/**
 * fullscreen.ts - Unified fullscreen for media content
 *
 * Replaces lightbox.ts. Same black-background container for all media types:
 * - Pictures: prev/next arrows, keyboard navigation
 * - Video: native controls
 * - Interactive iframes: exit button
 *
 * Uses the #lightbox HTML structure generated by media_collection.rs, or
 * builds a plain one on first open if the page has none. Opens from
 * media-collection grid items (`.media-item`), from the images of a
 * `:::gallery` (`.moss-gallery-link`) and from the content pictures of the page
 * (figures, lone images, grid-cell pictures). The arrows step through every
 * one of them in reading order.
 *
 * This script alone decides which pictures open; the build only decides
 * whether a page might have any. Without it the pictures stay plain images;
 * with it each becomes a button and the large view shows its figure caption,
 * links included. A picture inside a link, a hero, or an element with the
 * `no-viewer` class is left alone, as is one with neither alt text nor
 * caption.
 *
 * Every listener is delegated from the document and the pictures are found
 * when the reader acts, so a page the preview morphs in place works without a
 * reload.
 */



// Make this a module to allow declare global
export {};

interface MediaItem {
  type: "image" | "video" | "interactive";
  src: string;
  /** Plain-text caption; empty when the picture has none. */
  title: string;
  alt: string;
  articleUrl: string;
  /** The page's own caption element; its children, links included, are copied under the large view. */
  caption?: Element | null;
}

const PICTURES = "main figure.moss-image img, main p > picture:only-child > img, main p > img:only-child";
const SKIPPED = "a, .moss-hero, .no-viewer";
const TRIGGERS = `.media-item, .moss-gallery-link, ${PICTURES}`;

const LIGHTBOX = `<button class="lightbox-close" aria-label="Close">&times;</button>
<div class="lightbox-content"><img class="lightbox-image" src="" alt="" hidden /><video class="lightbox-video" controls playsinline hidden></video><iframe class="lightbox-iframe" hidden></iframe></div>
<div class="lightbox-caption"><p class="lightbox-title"></p><a class="lightbox-article-link" href="" hidden></a></div>
<button class="lightbox-nav lightbox-prev" aria-label="Previous">&lsaquo;</button>
<button class="lightbox-nav lightbox-next" aria-label="Next">&rsaquo;</button>`;

(function () {
  let items: MediaItem[] = [];
  let triggers: HTMLElement[] = [];
  let currentIndex = 0;

  // The viewer's element, made on first need when the page carries none.
  function lightboxEl(): HTMLElement {
    let el = document.getElementById("lightbox");
    if (!el) {
      el = document.createElement("div");
      el.id = "lightbox";
      el.className = "lightbox";
      el.setAttribute("role", "dialog");
      el.setAttribute("aria-modal", "true");
      el.setAttribute("aria-label", "Image viewer");
      el.hidden = true;
      el.tabIndex = -1;
      el.innerHTML = LIGHTBOX;
      document.body.append(el);
    }
    return el;
  }

  const isOpen = (): boolean => {
    const el = document.getElementById("lightbox");
    return !!el && el.isConnected && !el.hidden;
  };

  // A picture of the page body that opens: not inside a link, a hero or an
  // opted-out element, alone in its paragraph if it is not in a figure, and named.
  function pictureItem(img: HTMLImageElement): MediaItem | null {
    if (img.closest(SKIPPED)) return null;
    const para = img.closest("p");
    if (para && !img.closest("figure") && (para.textContent || "").trim() !== "") return null;
    const caption = img.closest("figure")?.querySelector("figcaption");
    const captionText = (caption?.textContent || "").trim();
    const name = img.alt || captionText;
    if (!name) return null;
    img.setAttribute("role", "button");
    img.setAttribute("aria-haspopup", "dialog");
    img.tabIndex = 0;
    img.dataset.viewer = "";
    if (!img.alt) img.setAttribute("aria-label", name);
    return { type: "image", src: img.src, title: captionText, alt: img.alt || name, articleUrl: "", caption };
  }

  function itemFor(trigger: HTMLElement): MediaItem | null {
    if (trigger instanceof HTMLImageElement) return pictureItem(trigger);
    if (trigger.closest(".no-viewer")) return null;
    // The viewer image's alt comes from the thumbnail's alt. An alt-only
    // gallery item has no title, so its caption stays empty while its
    // picture keeps the description.
    const thumbAlt = trigger.querySelector("img")?.alt;
    return {
      type: (trigger.dataset.type as MediaItem["type"]) || "image",
      src: trigger.dataset.src || (trigger as HTMLAnchorElement).href || "",
      title: trigger.dataset.title || "",
      alt: thumbAlt || trigger.dataset.title || "",
      articleUrl: trigger.dataset.article || "",
      caption: trigger.closest(".moss-gallery-item")?.querySelector(".moss-gallery-caption"),
    };
  }

  // Every picture the page offers right now, in reading order. Also gives each
  // content picture its button semantics.
  function collect(): { trigger: HTMLElement; item: MediaItem }[] {
    const found: { trigger: HTMLElement; item: MediaItem }[] = [];
    document.querySelectorAll<HTMLElement>(TRIGGERS).forEach((trigger) => {
      const item = itemFor(trigger);
      if (item) found.push({ trigger, item });
    });
    return found;
  }

  // The picture a click or key press on `target` belongs to, and its place in the page's sequence.
  function openFrom(target: EventTarget | null): boolean {
    if (!(target instanceof Element)) return false;
    const found = collect();
    const index = found.findIndex(({ trigger }) => trigger.contains(target));
    if (index < 0) return false;
    items = found.map((f) => f.item);
    triggers = found.map((f) => f.trigger);
    open(index);
    return true;
  }

  function open(index: number): void {
    const lightbox = lightboxEl();
    currentIndex = index;
    show(items[index]);
    // A single picture has nothing to step to.
    const single = items.length < 2;
    const prevButton = lightbox.querySelector<HTMLElement>(".lightbox-prev");
    const nextButton = lightbox.querySelector<HTMLElement>(".lightbox-next");
    if (prevButton) prevButton.hidden = single;
    if (nextButton) nextButton.hidden = single;
    lightbox.hidden = false;
    lightbox.focus();
    document.body.style.overflow = "hidden";
  }

  function close(): void {
    const lightbox = lightboxEl();
    lightbox.hidden = true;
    document.body.style.overflow = "";
    lightbox.querySelector<HTMLVideoElement>(".lightbox-video")?.pause();
    const iframe = lightbox.querySelector<HTMLIFrameElement>(".lightbox-iframe");
    if (iframe) iframe.src = "";
    // Return focus to the picture the reader was last looking at: the one
    // that opened the viewer, or the one they stepped to.
    triggers[currentIndex]?.focus();
  }

  function show(item: MediaItem): void {
    const lightbox = lightboxEl();
    const image = lightbox.querySelector<HTMLImageElement>(".lightbox-image");
    const video = lightbox.querySelector<HTMLVideoElement>(".lightbox-video");
    const iframe = lightbox.querySelector<HTMLIFrameElement>(".lightbox-iframe");
    const titleEl = lightbox.querySelector<HTMLElement>(".lightbox-title");
    const articleLink = lightbox.querySelector<HTMLAnchorElement>(".lightbox-article-link");

    // Hide all media elements
    if (image) image.hidden = true;
    if (video) {
      video.hidden = true;
      video.pause();
    }
    if (iframe) {
      iframe.hidden = true;
      iframe.src = "";
    }

    switch (item.type) {
      case "video":
        if (video) {
          video.src = item.src;
          video.hidden = false;
        }
        break;
      case "interactive":
        if (iframe) {
          iframe.src = item.src;
          iframe.hidden = false;
        }
        break;
      default:
        if (image) {
          image.src = item.src;
          image.alt = item.alt;
          image.hidden = false;
        }
    }

    if (titleEl) {
      if (item.caption) {
        // The copy must not repeat an id the page already has.
        const copy = item.caption.cloneNode(true) as Element;
        copy.querySelectorAll("[id]").forEach((el) => el.removeAttribute("id"));
        titleEl.replaceChildren(...Array.from(copy.childNodes));
      } else {
        titleEl.textContent = item.title;
      }
      // An alt-only picture has no title; an empty <p> would still leave its margin.
      titleEl.hidden = (titleEl.textContent || "").trim() === "";
    }
    if (articleLink) {
      articleLink.href = item.articleUrl;
      articleLink.hidden = !item.articleUrl;
    }
  }

  function step(by: number): void {
    if (items.length === 0) return;
    currentIndex = (currentIndex + by + items.length) % items.length;
    show(items[currentIndex]);
  }

  document.addEventListener("click", (e: MouseEvent) => {
    // The editor preview claims a click on a picture for its own gesture.
    if (e.defaultPrevented || !(e.target instanceof Element)) return;
    const lightbox = document.getElementById("lightbox");
    if (lightbox?.contains(e.target)) {
      if (e.target.closest(".lightbox-close")) close();
      else if (e.target.closest(".lightbox-next")) step(1);
      else if (e.target.closest(".lightbox-prev")) step(-1);
      else if (e.target === lightbox || e.target.closest(".lightbox-content") === e.target) close();
      return;
    }
    if (openFrom(e.target)) e.preventDefault();
  });

  document.addEventListener("keydown", (e: KeyboardEvent) => {
    if (e.defaultPrevented) return;
    if (!isOpen()) {
      if ((e.key === "Enter" || e.key === " ") && openFrom(e.target)) e.preventDefault();
      return;
    }
    if (e.key === "Tab") return trapFocus(e);
    // The viewer owns these keys while open; other page handlers (series
    // navigation) check defaultPrevented and must not also act on them.
    if (e.key === "Escape" || e.key === "ArrowRight" || e.key === "ArrowLeft") e.preventDefault();
    switch (e.key) {
      case "Escape":
        close();
        break;
      case "ArrowRight":
        step(1);
        break;
      case "ArrowLeft":
        step(-1);
        break;
    }
  });

  // Tab cycles through the viewer's own controls while it is open.
  function trapFocus(e: KeyboardEvent): void {
    const lightbox = lightboxEl();
    const controls = Array.from(
      lightbox.querySelectorAll<HTMLElement>("button:not([hidden]), a[href]:not([hidden])")
    );
    const first = controls[0];
    const last = controls[controls.length - 1];
    const active = document.activeElement;
    if (!lightbox.contains(active) || (e.shiftKey && (active === first || active === lightbox))) {
      e.preventDefault();
      (e.shiftKey ? last : first)?.focus();
    } else if (!e.shiftKey && active === last) {
      e.preventDefault();
      first?.focus();
    }
  }

  // Touch swipe support
  let touchStartX = 0;
  const inViewer = (e: Event): boolean =>
    e.target instanceof Node && !!document.getElementById("lightbox")?.contains(e.target);

  document.addEventListener(
    "touchstart",
    (e: TouchEvent) => {
      if (inViewer(e)) touchStartX = e.touches[0].clientX;
    },
    { passive: true }
  );

  document.addEventListener(
    "touchend",
    (e: TouchEvent) => {
      if (!inViewer(e)) return;
      const diff = e.changedTouches[0].clientX - touchStartX;
      if (Math.abs(diff) > 50) step(diff > 0 ? -1 : 1);
    },
    { passive: true }
  );

  // Give the pictures their button semantics on load and whenever the page
  // gains content, so a keyboard reader can reach them.
  collect();
  new MutationObserver(collect).observe(document.documentElement, { childList: true, subtree: true });
})();
